'use strict';

// Version strings as the package index writes them, and the ranges a manifest
// pins its dependencies to. The install planner reads both through here.

function parse(version) {
  const m = /^(\d+)\.(\d+)\.(\d+)/.exec(String(version).trim());
  if (!m) return null;
  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]) };
}

function compare(a, b) {
  const left = parse(a);
  const right = parse(b);
  if (left === null || right === null) return 0;
  if (left.major !== right.major) return left.major < right.major ? -1 : 1;
  if (left.minor !== right.minor) return left.minor < right.minor ? -1 : 1;
  if (left.patch !== right.patch) return left.patch < right.patch ? -1 : 1;
  return 0;
}

// Most of the manifest still pins a dependency to one exact version, so this
// has never had to answer anything wider than that.
function satisfies(version, range) {
  if (parse(version) === null || parse(range) === null) return false;
  return compare(version, range) === 0;
}

module.exports = { parse, compare, satisfies };

