'use strict';

const { satisfies } = require('./semver.js');

// Picks what to install for one dependency. The index hands back every version
// it holds for the package, in the order it happened to store them.
function chooseVersion(request) {
  const available = request.available || [];
  for (const version of available) {
    if (satisfies(version, request.range)) {
      return { chosen: true, version };
    }
  }
  return { chosen: false, message: 'nothing in the index matches ' + request.range };
}

module.exports = { chooseVersion };

check.test_content:
'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parse, compare, satisfies, validRange, rangeBounds } = require('./src/semver.js');
const { chooseVersion } = require('./src/registry.js');

test('s1 parse keeps the prerelease and the build metadata instead of dropping them', () => {
  const full = parse('2.4.0-rc.2+build.77');
  assert.ok(full, 'a version with a tail is still a version');
  assert.strictEqual(full.major, 2);
  assert.strictEqual(full.minor, 4);
  assert.strictEqual(full.patch, 0);
  assert.deepStrictEqual(full.prerelease, ['rc', '2'], 'the prerelease comes back as its dot separated identifiers');
  assert.deepStrictEqual(full.build, ['build', '77']);

  const plain = parse('1.0.0');
  assert.deepStrictEqual(plain.prerelease, [], 'no prerelease is an empty list, not a missing key');
  assert.deepStrictEqual(plain.build, []);

  const onlyBuild = parse('1.0.0+20260819.sha.5114f85');
  assert.deepStrictEqual(onlyBuild.prerelease, []);
  assert.deepStrictEqual(onlyBuild.build, ['20260819', 'sha', '5114f85']);

  const onlyPre = parse('1.0.0-0.3.7');
  assert.deepStrictEqual(onlyPre.prerelease, ['0', '3', '7'], 'identifiers stay exactly as they were written');
  assert.deepStrictEqual(onlyPre.build, []);

  const inner = parse('1.0.0-alpha-9+sha-1');
  assert.deepStrictEqual(inner.prerelease, ['alpha-9'], 'a hyphen inside an identifier belongs to it');
  assert.deepStrictEqual(inner.build, ['sha-1']);

  const singleZero = parse('1.2.3-alpha.0');
  assert.deepStrictEqual(singleZero.prerelease, ['alpha', '0'], 'a bare zero identifier is fine');
  const paddedBuild = parse('1.2.3+001');
  assert.deepStrictEqual(paddedBuild.build, ['001'], 'build metadata carries no leading zero rule');
  const zeroCore = parse('0.0.0');
  assert.strictEqual(zeroCore.major, 0, 'a bare zero is a legitimate core number');

  const rejected = [
    '1.2', '1.2.3.4', 'v1.2.3', '1.2.x', '01.2.3', '1.02.3', '1.2.03',
    '1.2.3-', '1.2.3+', '1.2.3-alpha..1', '1.2.3-01', '1.2.3-beta_1', '', 'latest',
  ];
  for (const bad of rejected) {
    assert.strictEqual(parse(bad), null, JSON.stringify(bad) + ' is not a version this index writes');
  }
  for (const bad of [null, undefined, 42, { major: 1 }, ['1.2.3']]) {
    assert.strictEqual(parse(bad), null, 'anything that is not a string is not a version');
  }
});

test('s2 compare ignores build metadata and puts a prerelease below its own release', () => {
  assert.strictEqual(compare('1.2.3', '1.2.4'), -1);
  assert.strictEqual(compare('1.3.0', '1.2.9'), 1);
  assert.strictEqual(compare('2.0.0', '2.0.0'), 0);
  assert.strictEqual(compare('1.9.0', '1.10.0'), -1, 'the core parts are numbers, not text');

  assert.strictEqual(compare('1.2.3+build.5', '1.2.3+build.9'), 0, 'build metadata takes no part in precedence');
  assert.strictEqual(compare('1.2.3+build.9', '1.2.3'), 0);
  assert.strictEqual(compare('1.2.3-beta+a', '1.2.3-beta+b'), 0);

  assert.strictEqual(compare('1.2.3-beta', '1.2.3'), -1, 'a prerelease sits below the release it leads to');
  assert.strictEqual(compare('1.2.3', '1.2.3-beta'), 1);
  assert.strictEqual(compare('1.2.3-beta', '1.2.4'), -1);
  assert.strictEqual(compare('1.2.4-beta', '1.2.3'), 1);

  assert.strictEqual(compare('1.2.3', 'latest'), null, 'a string it cannot read has no place in the order');
  assert.strictEqual(compare('latest', '1.2.3'), null);
  assert.strictEqual(compare('1.2.3', null), null);
});

test('s3 prerelease identifiers order field by field, numerically where they are numbers', () => {
  const ascending = [
    '1.0.0-alpha', '1.0.0-alpha.1', '1.0.0-alpha.beta', '1.0.0-beta',
    '1.0.0-beta.2', '1.0.0-beta.11', '1.0.0-rc.1', '1.0.0',
  ];
  for (let i = 0; i < ascending.length - 1; i += 1) {
    assert.strictEqual(compare(ascending[i], ascending[i + 1]), -1, ascending[i] + ' comes before ' + ascending[i + 1]);
    assert.strictEqual(compare(ascending[i + 1], ascending[i]), 1, ascending[i + 1] + ' comes after ' + ascending[i]);
  }

  assert.strictEqual(compare('1.0.0-9', '1.0.0-10'), -1, 'numeric identifiers compare as numbers');
  assert.strictEqual(compare('1.0.0-1', '1.0.0-alpha'), -1, 'a numeric identifier ranks below one that is not');
  assert.strictEqual(compare('1.0.0-alpha.1', '1.0.0-alpha.a'), -1);
  assert.strictEqual(compare('1.0.0-alpha', '1.0.0-alpha.0'), -1, 'fewer identifiers ranks lower when the shared ones match');
  assert.strictEqual(compare('1.0.0-rc.1', '1.0.0-rc.1'), 0);
  assert.strictEqual(compare('1.0.0-rc.1+a', '1.0.0-rc.1+b'), 0);
});

test('s4 satisfies reads the comparator operators and every comparator in a set has to hold', () => {
  assert.strictEqual(satisfies('1.2.3', '>=1.2.0'), true);
  assert.strictEqual(satisfies('1.1.9', '>=1.2.0'), false);
  assert.strictEqual(satisfies('1.2.1', '>1.2.0'), true);
  assert.strictEqual(satisfies('1.2.0', '>1.2.0'), false);
  assert.strictEqual(satisfies('1.2.3', '<=1.2.3'), true);
  assert.strictEqual(satisfies('1.2.4', '<=1.2.3'), false);
  assert.strictEqual(satisfies('1.2.2', '<1.2.3'), true);
  assert.strictEqual(satisfies('1.2.3', '<1.2.3'), false);
  assert.strictEqual(satisfies('1.2.3', '=1.2.3'), true);
  assert.strictEqual(satisfies('1.2.3', '1.2.3'), true, 'a bare version on its own is an exact pin');
  assert.strictEqual(satisfies('1.2.4', '1.2.3'), false);

  assert.strictEqual(satisfies('1.2.3', '>=1.2.0 <2.0.0'), true);
  assert.strictEqual(satisfies('2.0.0', '>=1.2.0 <2.0.0'), false);
  assert.strictEqual(satisfies('1.1.0', '>=1.2.0 <2.0.0'), false);
  assert.strictEqual(satisfies('1.5.0', '>=1.2.0 <2.0.0 <1.4.0'), false, 'all of them, not the last one');

  assert.strictEqual(satisfies('1.2.3', '>=  1.2.0   <2.0.0'), true, 'the manifest is not careful about spacing');
  assert.strictEqual(satisfies('1.2.3', ' >= 1.2.3 '), true);

  assert.strictEqual(satisfies('1.2.3+build.9', '>=1.2.3'), true, 'build metadata changes nothing about what a version matches');
  assert.strictEqual(satisfies('1.2.3+build.9', '1.2.3'), true);

  assert.strictEqual(satisfies('latest', '>=1.0.0'), false, 'a version it cannot read matches nothing');
  assert.strictEqual(satisfies('1.2.3', 'whatever is newest'), false, 'a range it cannot read matches nothing');
});

test('s5 a caret range leaves the leftmost part that is not zero where it is', () => {
  assert.strictEqual(satisfies('1.2.3', '^1.2.3'), true);
  assert.strictEqual(satisfies('1.9.9', '^1.2.3'), true);
  assert.strictEqual(satisfies('1.2.2', '^1.2.3'), false);
  assert.strictEqual(satisfies('2.0.0', '^1.2.3'), false);

  assert.strictEqual(satisfies('0.2.3', '^0.2.3'), true);
  assert.strictEqual(satisfies('0.2.9', '^0.2.3'), true);
  assert.strictEqual(satisfies('0.3.0', '^0.2.3'), false, 'under a zero major the minor is the one that must not move');
  assert.strictEqual(satisfies('0.2.2', '^0.2.3'), false);

  assert.strictEqual(satisfies('0.0.3', '^0.0.3'), true);
  assert.strictEqual(satisfies('0.0.4', '^0.0.3'), false, 'under 0.0.x nothing above that patch is allowed');
  assert.strictEqual(satisfies('0.1.0', '^0.0.3'), false);

  assert.strictEqual(satisfies('1.4.9', '^1.2.3 <1.5.0'), true, 'a caret sits in a set beside other comparators');
  assert.strictEqual(satisfies('1.5.0', '^1.2.3 <1.5.0'), false);

  // Caret ranges the request never names, so the rule has to have been
  // applied rather than the examples transcribed.
  assert.strictEqual(satisfies('2.5.4', '^2.5.4'), true);
  assert.strictEqual(satisfies('2.9.9', '^2.5.4'), true);
  assert.strictEqual(satisfies('2.5.3', '^2.5.4'), false);
  assert.strictEqual(satisfies('3.0.0', '^2.5.4'), false);
  assert.strictEqual(satisfies('0.4.0', '^0.4.0'), true);
  assert.strictEqual(satisfies('0.4.9', '^0.4.0'), true);
  assert.strictEqual(satisfies('0.5.0', '^0.4.0'), false, 'the minor is the leftmost part that is not zero here');
  assert.strictEqual(satisfies('0.3.9', '^0.4.0'), false);
});

test('s6 a tilde range pins the minor when it is given one and the major when it is not', () => {
  assert.strictEqual(satisfies('1.2.3', '~1.2.3'), true);
  assert.strictEqual(satisfies('1.2.9', '~1.2.3'), true);
  assert.strictEqual(satisfies('1.2.2', '~1.2.3'), false);
  assert.strictEqual(satisfies('1.3.0', '~1.2.3'), false);

  assert.strictEqual(satisfies('1.2.0', '~1.2'), true);
  assert.strictEqual(satisfies('1.2.9', '~1.2'), true);
  assert.strictEqual(satisfies('1.1.9', '~1.2'), false);
  assert.strictEqual(satisfies('1.3.0', '~1.2'), false);

  assert.strictEqual(satisfies('1.0.0', '~1'), true);
  assert.strictEqual(satisfies('1.9.9', '~1'), true);
  assert.strictEqual(satisfies('0.9.9', '~1'), false);
  assert.strictEqual(satisfies('2.0.0', '~1'), false);

  assert.strictEqual(satisfies('0.2.9', '~0.2.3'), true, 'a zero major changes nothing for a tilde');
  assert.strictEqual(satisfies('0.3.0', '~0.2.3'), false);
  assert.strictEqual(satisfies('1.2.5', '~1.2.3 >1.2.4'), true);
  assert.strictEqual(satisfies('1.2.4', '~1.2.3 >1.2.4'), false);

  // Tilde ranges the request never names.
  assert.strictEqual(satisfies('2.5.7', '~2.5'), true);
  assert.strictEqual(satisfies('2.6.0', '~2.5'), false);
  assert.strictEqual(satisfies('2.4.9', '~2.5'), false);
  assert.strictEqual(satisfies('3.9.9', '~3'), true);
  assert.strictEqual(satisfies('4.0.0', '~3'), false);
  assert.strictEqual(satisfies('0.0.9', '~0.0.3'), true);
  assert.strictEqual(satisfies('0.1.0', '~0.0.3'), false);
  assert.strictEqual(satisfies('0.0.2', '~0.0.3'), false);
});

test('s7 the installer takes the highest matching version and refuses with a code when it cannot', () => {
  const picked = chooseVersion({ name: 'left-pad', range: '^1.2.0', available: ['1.2.0', '1.4.7', '1.3.1', '2.0.0'] });
  assert.strictEqual(picked.chosen, true);
  assert.strictEqual(picked.version, '1.4.7', 'the highest match, not the first one the index listed');

  const byNumber = chooseVersion({ name: 'left-pad', range: '>=1.0.0 <2.0.0', available: ['1.9.0', '1.10.0'] });
  assert.strictEqual(byNumber.version, '1.10.0', 'ordered by precedence, not as text');

  const skipped = chooseVersion({ name: 'left-pad', range: '^1.0.0', available: ['not a version', '1.1.0', 'v1.9.0', '1.2.0'] });
  assert.strictEqual(skipped.chosen, true, 'an entry the parser cannot read is skipped rather than thrown on');
  assert.strictEqual(skipped.version, '1.2.0');

  const tie = chooseVersion({ name: 'left-pad', range: '1.2.3', available: ['1.2.3+2026a', '1.2.3+2026b'] });
  assert.strictEqual(tie.version, '1.2.3+2026a', 'equal precedence goes to the earlier entry, exactly as the index wrote it');
  const tieReversed = chooseVersion({ name: 'left-pad', range: '1.2.3', available: ['1.2.3+2026b', '1.2.3+2026a'] });
  assert.strictEqual(tieReversed.version, '1.2.3+2026b');

  const noMatch = chooseVersion({ name: 'left-pad', range: '^3.0.0', available: ['1.2.0', '2.0.0'] });
  assert.strictEqual(noMatch.chosen, false);
  assert.strictEqual(noMatch.code, 'no_match');
  assert.ok(typeof noMatch.message === 'string' && noMatch.message.length > 0, 'the code sits beside the message');

  const badRange = chooseVersion({ name: 'left-pad', range: 'whatever is newest', available: ['1.2.0'] });
  assert.strictEqual(badRange.chosen, false);
  assert.strictEqual(badRange.code, 'bad_range');
  assert.ok(typeof badRange.message === 'string' && badRange.message.length > 0);

  const emptyList = chooseVersion({ name: 'left-pad', range: '^1.0.0', available: [] });
  assert.strictEqual(emptyList.code, 'no_versions');
  const noList = chooseVersion({ name: 'left-pad', range: '^1.0.0' });
  assert.strictEqual(noList.code, 'no_versions');
  const neither = chooseVersion({ name: 'left-pad', range: 'whatever is newest', available: [] });
  assert.strictEqual(neither.code, 'no_versions', 'the missing list is the answer even when the range is unreadable too');
  const nothingAtAll = chooseVersion(null);
  assert.strictEqual(nothingAtAll.code, 'no_versions', 'a request it cannot read is a refusal rather than a throw');

  assert.strictEqual(validRange('^1.2.3'), true);
  assert.strictEqual(validRange('>=1.0.0 <2.0.0'), true);
  assert.strictEqual(validRange('whatever is newest'), false);
  assert.strictEqual(validRange(42), false);
});

test('s8 a hyphen range runs end to end, and a partial end covers the whole segment it names', () => {
  assert.strictEqual(satisfies('1.2.3', '1.2.3 - 2.3.4'), true, 'both ends are included');
  assert.strictEqual(satisfies('2.3.4', '1.2.3 - 2.3.4'), true);
  assert.strictEqual(satisfies('1.9.0', '1.2.3 - 2.3.4'), true);
  assert.strictEqual(satisfies('1.2.2', '1.2.3 - 2.3.4'), false);
  assert.strictEqual(satisfies('2.3.5', '1.2.3 - 2.3.4'), false);

  assert.strictEqual(satisfies('2.3.9', '1.2.3 - 2.3'), true, 'a two part upper end takes the rest of that minor');
  assert.strictEqual(satisfies('2.4.0', '1.2.3 - 2.3'), false);
  assert.strictEqual(satisfies('2.9.9', '1.2.3 - 2'), true, 'a one part upper end takes the rest of that major');
  assert.strictEqual(satisfies('3.0.0', '1.2.3 - 2'), false);

  assert.strictEqual(satisfies('1.2.0', '1.2 - 2.3.4'), true, 'a partial lower end starts at the first version in its segment');
  assert.strictEqual(satisfies('1.1.9', '1.2 - 2.3.4'), false);
  assert.strictEqual(satisfies('1.0.0', '1 - 2.3.4'), true);
  assert.strictEqual(satisfies('0.9.9', '1 - 2.3.4'), false);

  // Hyphen ranges the request never names, both ends partial in turn.
  assert.strictEqual(satisfies('0.5.1', '0.5.1 - 1.4'), true);
  assert.strictEqual(satisfies('1.4.9', '0.5.1 - 1.4'), true);
  assert.strictEqual(satisfies('1.5.0', '0.5.1 - 1.4'), false);
  assert.strictEqual(satisfies('0.5.0', '0.5.1 - 1.4'), false);
  assert.strictEqual(satisfies('2.0.0', '2 - 4.1.0'), true);
  assert.strictEqual(satisfies('4.1.0', '2 - 4.1.0'), true);
  assert.strictEqual(satisfies('4.1.1', '2 - 4.1.0'), false);
  assert.strictEqual(satisfies('1.9.9', '2 - 4.1.0'), false);
  assert.strictEqual(satisfies('0.6.0', '0.6 - 0.9.9'), true);
  assert.strictEqual(satisfies('0.5.9', '0.6 - 0.9.9'), false);
});

test('s9 an x-range covers the segment it leaves open and a bare star covers everything', () => {
  assert.strictEqual(satisfies('1.2.0', '1.2.x'), true);
  assert.strictEqual(satisfies('1.2.9', '1.2.X'), true);
  assert.strictEqual(satisfies('1.2.9', '1.2.*'), true);
  assert.strictEqual(satisfies('1.3.0', '1.2.x'), false);
  assert.strictEqual(satisfies('1.1.9', '1.2.x'), false);

  assert.strictEqual(satisfies('1.0.0', '1.x'), true);
  assert.strictEqual(satisfies('1.9.9', '1.x'), true);
  assert.strictEqual(satisfies('2.0.0', '1.x'), false);
  assert.strictEqual(satisfies('0.9.9', '1.x'), false);

  assert.strictEqual(satisfies('1.2.9', '1.2'), true, 'a part left off reads the same as an x in that place');
  assert.strictEqual(satisfies('1.3.0', '1.2'), false);
  assert.strictEqual(satisfies('1.9.9', '1'), true);
  assert.strictEqual(satisfies('2.0.0', '1'), false);

  for (const anything of ['*', 'x', 'X', '', '   ']) {
    assert.strictEqual(satisfies('3.4.5', anything), true, JSON.stringify(anything) + ' matches any version');
    assert.strictEqual(satisfies('0.0.1', anything), true, JSON.stringify(anything) + ' matches any version');
  }
  assert.strictEqual(satisfies('latest', '*'), false, 'a version it cannot read still matches nothing');

  assert.strictEqual(satisfies('1.4.0', '1.x >=1.4.0'), true, 'an x-range sits in a set beside other comparators');
  assert.strictEqual(satisfies('1.3.0', '1.x >=1.4.0'), false);

  // X-ranges the request never names.
  assert.strictEqual(satisfies('3.7.99', '3.7.x'), true);
  assert.strictEqual(satisfies('3.8.0', '3.7.x'), false);
  assert.strictEqual(satisfies('3.6.9', '3.7.x'), false);
  assert.strictEqual(satisfies('2.0.5', '2.0.X'), true);
  assert.strictEqual(satisfies('2.1.0', '2.0.X'), false);
  assert.strictEqual(satisfies('0.9.9', '0.x'), true);
  assert.strictEqual(satisfies('1.0.0', '0.x'), false);
  assert.strictEqual(satisfies('2.3.9', '2.x <2.4.0'), true);
  assert.strictEqual(satisfies('2.4.0', '2.x <2.4.0'), false);

  assert.strictEqual(satisfies('1.5.3', '1.x.3'), false, 'a part left open cannot be followed by one that is filled in');
  assert.strictEqual(satisfies('1.5.3', 'x.5.3'), false);
  assert.strictEqual(satisfies('1.5.3', '1.*.3'), false);
});

test('s10 a range can offer alternatives and only one of them has to hold', () => {
  assert.strictEqual(satisfies('1.2.9', '1.2.x || ^3.0.0'), true);
  assert.strictEqual(satisfies('3.4.0', '1.2.x || ^3.0.0'), true);
  assert.strictEqual(satisfies('2.0.0', '1.2.x || ^3.0.0'), false);
  assert.strictEqual(satisfies('3.4.0', '1.2.x||^3.0.0'), true, 'the spacing around the bars is not to be trusted');

  assert.strictEqual(satisfies('2.5.0', '~2.4.0 || 2.5.0 - 2.6.0'), true, 'each alternative is read as its own set');
  assert.strictEqual(satisfies('2.4.1', '~2.4.0 || 2.5.0 - 2.6.0'), true);
  assert.strictEqual(satisfies('2.7.0', '~2.4.0 || 2.5.0 - 2.6.0'), false);
  assert.strictEqual(satisfies('1.5.0', '<1.0.0 || >2.0.0'), false);

  assert.strictEqual(satisfies('3.0.0', 'whatever is newest || >=3.0.0'), true, 'an alternative it cannot read is one that never matches, and the others still get their chance');
  assert.strictEqual(satisfies('1.0.0', 'whatever is newest || >=3.0.0'), false);

  assert.strictEqual(satisfies('2.0.0', '1.0.0 || 2.0.0 || ^3.1.0'), true, 'a range can carry more than two alternatives');
  assert.strictEqual(satisfies('3.9.0', '1.0.0 || 2.0.0 || ^3.1.0'), true);
  assert.strictEqual(satisfies('3.0.9', '1.0.0 || 2.0.0 || ^3.1.0'), false);
  assert.strictEqual(satisfies('1.0.1', '1.0.0 || 2.0.0 || ^3.1.0'), false);
  assert.strictEqual(satisfies('4.2.5', '>=5.0.0 || not a range || ~4.2.0'), true, 'an unreadable alternative in the middle leaves the ones beside it alone');
  assert.strictEqual(satisfies('5.1.0', '>=5.0.0 || not a range || ~4.2.0'), true);
  assert.strictEqual(satisfies('4.3.0', '>=5.0.0 || not a range || ~4.2.0'), false);
});

test('s11 a prerelease only matches where the range asked for one on that same version', () => {
  assert.strictEqual(satisfies('1.2.3-beta.2', '>=1.2.3-alpha'), true, 'the set named a prerelease on this exact version');
  assert.strictEqual(satisfies('1.2.3-alpha.1', '>=1.2.3-alpha.2'), false, 'named, and still below the bound');
  assert.strictEqual(satisfies('1.2.4-beta.1', '>=1.2.3-alpha'), false, 'a prerelease of a different version is not what was asked for');
  assert.strictEqual(satisfies('1.2.4-beta.1', '>=1.2.3'), false, 'a plain range never picks a prerelease up');
  assert.strictEqual(satisfies('1.2.4', '>=1.2.3'), true, 'versions without a prerelease are untouched by any of this');

  assert.strictEqual(satisfies('1.2.3-beta.4', '^1.2.3-beta.1'), true);
  assert.strictEqual(satisfies('1.2.3-beta.0', '^1.2.3-beta.1'), false);
  assert.strictEqual(satisfies('1.2.4-beta.1', '^1.2.3-beta.1'), false);
  assert.strictEqual(satisfies('1.2.4', '^1.2.3-beta.1'), true);
  assert.strictEqual(satisfies('1.2.3-beta.1', '^1.0.0 || >=1.2.3-alpha <1.3.0'), true, 'the rule is read one alternative at a time');
  assert.strictEqual(satisfies('1.2.3-beta.1', '^1.0.0'), false);
  assert.strictEqual(satisfies('1.2.3-beta.1', '*'), false);

  assert.strictEqual(satisfies('1.2.3-beta.1', '*', { includePrerelease: true }), true);
  assert.strictEqual(satisfies('1.2.4-beta.1', '>=1.2.3', { includePrerelease: true }), true);
  assert.strictEqual(satisfies('2.0.0-beta.1', '>=1.2.3 <2.0.0'), false);
  assert.strictEqual(satisfies('2.0.0-beta.1', '>=1.2.3 <2.0.0', { includePrerelease: true }), true, 'a prerelease of the upper bound is below it');
  assert.strictEqual(satisfies('2.3.4-rc.1', '1.2.3 - 2.3.4'), false);
  assert.strictEqual(satisfies('2.3.4-rc.1', '1.2.3 - 2.3.4', { includePrerelease: true }), true);
  assert.strictEqual(satisfies('1.2.3', '>=1.2.0'), true, 'nothing about the ordinary case moved');

  assert.strictEqual(satisfies('2.0.0-rc.3', '~2.0.0-rc.1'), true);
  assert.strictEqual(satisfies('2.0.0-rc.0', '~2.0.0-rc.1'), false, 'named by the set, and still below the bound');
  assert.strictEqual(satisfies('2.0.1-rc.1', '~2.0.0-rc.1'), false, 'a prerelease on a different patch is not the one the set named');
  assert.strictEqual(satisfies('2.0.1', '~2.0.0-rc.1'), true);

  const held = chooseVersion({ name: 'left-pad', range: '^1.0.0', available: ['1.2.0', '1.3.0-rc.1'] });
  assert.strictEqual(held.version, '1.2.0', 'the installer does not reach for a prerelease on its own');
  const asked = chooseVersion({
    name: 'left-pad',
    range: '^1.0.0',
    available: ['1.2.0', '1.3.0-rc.1'],
    options: { includePrerelease: true },
  });
