  assert.strictEqual(hyphen.min.version, '1.2.3');
  assert.strictEqual(hyphen.min.inclusive, true);
  assert.strictEqual(hyphen.max.version, '2.3.4');
  assert.strictEqual(hyphen.max.inclusive, true, 'a hyphen range takes in its upper end');

