  assert.strictEqual(exact.min.version, '1.2.3');
  assert.strictEqual(exact.min.inclusive, true);
  assert.strictEqual(exact.max.version, '1.2.3');
  assert.strictEqual(exact.max.inclusive, true, 'an exact pin bounds both sides');

