'use strict';

// Version strings as the package index writes them, and the ranges a manifest
// pins its dependencies to. The install planner reads both through here.

const DIGITS = /^\d+$/;
const VERSION = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
const PARTIAL = /^(\d+|[xX*])(?:\.(\d+|[xX*]))?(?:\.(\d+|[xX*]))?(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;

function leadingZero(digits) {
  return digits.length > 1 && digits[0] === '0';
}

function parse(version) {
  if (typeof version !== 'string') return null;
  const m = VERSION.exec(version);
  if (!m) return null;
  if (leadingZero(m[1]) || leadingZero(m[2]) || leadingZero(m[3])) return null;
  const prerelease = m[4] === undefined ? [] : m[4].split('.');
  const build = m[5] === undefined ? [] : m[5].split('.');
  for (const id of prerelease) {
    if (id.length === 0) return null;
    if (DIGITS.test(id) && leadingZero(id)) return null;
  }
  for (const id of build) {
    if (id.length === 0) return null;
  }
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    prerelease,
    build,
  };
}

function cmpNumber(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

// Build metadata takes no part in precedence, so it never reaches this.
function cmpPrerelease(a, b) {
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1;
  if (b.length === 0) return -1;
  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i += 1) {
    const left = a[i];
    const right = b[i];
    const leftNumeric = DIGITS.test(left);
    const rightNumeric = DIGITS.test(right);
    if (leftNumeric && rightNumeric) {
      const byNumber = cmpNumber(Number(left), Number(right));
      if (byNumber !== 0) return byNumber;
    } else if (leftNumeric) {
      return -1;
    } else if (rightNumeric) {
      return 1;
    } else {
      const byText = cmpNumber(left, right);
      if (byText !== 0) return byText;
    }
  }
  return cmpNumber(a.length, b.length);
}

function compareParsed(a, b) {
  return (
    cmpNumber(a.major, b.major) ||
    cmpNumber(a.minor, b.minor) ||
    cmpNumber(a.patch, b.patch) ||
    cmpPrerelease(a.prerelease, b.prerelease)
  );
}

function compare(a, b) {
  const left = parse(a);
  const right = parse(b);
  if (left === null || right === null) return null;
  return compareParsed(left, right);
}

// --- ranges -----------------------------------------------------------------

function isWildcard(part) {
  return part === undefined || part === '' || part === 'x' || part === 'X' || part === '*';
}

// A version with parts left off or wildcarded, as a range is allowed to write
// it. Returns null for anything the matcher cannot read.
function splitPartial(text) {
  const m = PARTIAL.exec(text);
  if (!m) return null;
  const parts = [m[1], m[2], m[3]];
  let seenWildcard = false;
  for (const part of parts) {
    if (isWildcard(part)) {
      seenWildcard = true;
    } else {
      if (seenWildcard) return null;
      if (leadingZero(part)) return null;
    }
  }
  return { major: m[1], minor: m[2], patch: m[3], pre: m[4] };
}

function number(part) {
  return isWildcard(part) ? 0 : Number(part);
}

function at(major, minor, patch, pre) {
  const text = major + '.' + minor + '.' + patch + (pre ? '-' + pre : '');
  return parse(text);
}

function bounded(lower, upper) {
  if (lower === null || upper === null) return null;
  return [{ op: '>=', version: lower }, { op: '<', version: upper }];
}

function expandBare(text) {
  const p = splitPartial(text);
  if (p === null) return null;
  if (isWildcard(p.major)) return [];
  const major = number(p.major);
  const minor = number(p.minor);
  if (isWildcard(p.minor)) return bounded(at(major, 0, 0), at(major + 1, 0, 0));
  if (isWildcard(p.patch)) return bounded(at(major, minor, 0), at(major, minor + 1, 0));
  const exact = at(major, minor, number(p.patch), p.pre);
  if (exact === null) return null;
  return [{ op: '=', version: exact }];
}

// The leftmost part that is not zero is the one a caret will not move.
function expandCaret(text) {
  const p = splitPartial(text);
  if (p === null) return null;
  if (isWildcard(p.major)) return [];
  const major = number(p.major);
  const minor = number(p.minor);
  const patch = number(p.patch);
  const lower = at(major, minor, patch, p.pre);
  let upper;
  if (isWildcard(p.minor)) {
    upper = at(major + 1, 0, 0);
  } else if (isWildcard(p.patch)) {
    upper = major === 0 ? at(0, minor + 1, 0) : at(major + 1, 0, 0);
  } else if (major !== 0) {
    upper = at(major + 1, 0, 0);
  } else if (minor !== 0) {
    upper = at(0, minor + 1, 0);
  } else {
    upper = at(0, 0, patch + 1);
  }
  return bounded(lower, upper);
}

function expandTilde(text) {
  const p = splitPartial(text);
  if (p === null) return null;
  if (isWildcard(p.major)) return [];
  const major = number(p.major);
  const minor = number(p.minor);
  const lower = at(major, minor, number(p.patch), p.pre);
  const upper = isWildcard(p.minor) ? at(major + 1, 0, 0) : at(major, minor + 1, 0);
  return bounded(lower, upper);
}

function expandOperator(op, text) {
  const p = splitPartial(text);
  if (p === null) return null;
  if (isWildcard(p.major)) return [];
  const version = at(number(p.major), number(p.minor), number(p.patch), p.pre);
  if (version === null) return null;
  return [{ op, version }];
}

function expandHyphen(lowText, highText) {
  const low = splitPartial(lowText);
  const high = splitPartial(highText);
  if (low === null || high === null) return null;
  const out = [];
  if (!isWildcard(low.major)) {
    const from = at(number(low.major), number(low.minor), number(low.patch), low.pre);
    if (from === null) return null;
    out.push({ op: '>=', version: from });
  }
  if (!isWildcard(high.major)) {
    const major = number(high.major);
    const minor = number(high.minor);
    let to;
    let op;
    if (isWildcard(high.minor)) {
      to = at(major + 1, 0, 0);
      op = '<';
    } else if (isWildcard(high.patch)) {
      to = at(major, minor + 1, 0);
      op = '<';
    } else {
      to = at(major, minor, number(high.patch), high.pre);
      op = '<=';
    }
    if (to === null) return null;
    out.push({ op, version: to });
  }
  return out;
}

function expandComparator(part) {
  let m = /^\^(.+)$/.exec(part);
  if (m) return expandCaret(m[1]);
  m = /^~(.+)$/.exec(part);
  if (m) return expandTilde(m[1]);
  m = /^(>=|<=|>|<|=)(.+)$/.exec(part);
  if (m) return expandOperator(m[1], m[2]);
  return expandBare(part);
}

// One alternative out of a range: comparators separated by spaces, all of which
// have to hold. Returns null when any part of it cannot be read.
function comparatorSet(text) {
  const trimmed = text.trim();
  if (trimmed === '') return [];
  const hyphen = /^(\S+)\s+-\s+(\S+)$/.exec(trimmed);
  if (hyphen) return expandHyphen(hyphen[1], hyphen[2]);
  const tokens = trimmed.split(/\s+/);
  const parts = [];
  for (let i = 0; i < tokens.length; i += 1) {
    if (/^(>=|<=|>|<|=|\^|~)$/.test(tokens[i]) && i + 1 < tokens.length) {
      parts.push(tokens[i] + tokens[i + 1]);
      i += 1;
    } else {
      parts.push(tokens[i]);
    }
  }
  const out = [];
  for (const part of parts) {
    const expanded = expandComparator(part);
    if (expanded === null) return null;
    for (const comparator of expanded) out.push(comparator);
  }
  return out;
}

function comparatorSets(range) {
  if (typeof range !== 'string') return null;
  return range.split('||').map((chunk) => comparatorSet(chunk));
}

function validRange(range) {
  const sets = comparatorSets(range);
  if (sets === null) return false;
  return sets.every((set) => set !== null);
}

function holds(version, comparator) {
  const order = compareParsed(version, comparator.version);
  switch (comparator.op) {
    case '>': return order > 0;
    case '>=': return order >= 0;
    case '<': return order < 0;
    case '<=': return order <= 0;
    default: return order === 0;
  }
}

// A prerelease is only ever picked up by a set that asked for one on that same
// major.minor.patch.
function namedByTheSet(version, set) {
  for (const comparator of set) {
    const bound = comparator.version;
    if (
      bound.prerelease.length > 0 &&
      bound.major === version.major &&
      bound.minor === version.minor &&
      bound.patch === version.patch
    ) {
      return true;
    }
  }
  return false;
}

function setAllows(version, set, includePrerelease) {
  for (const comparator of set) {
    if (!holds(version, comparator)) return false;
  }
  if (version.prerelease.length > 0 && !includePrerelease) {
    return namedByTheSet(version, set);
  }
  return true;
}

function satisfies(version, range, options) {
  const parsed = parse(version);
  if (parsed === null) return false;
  const sets = comparatorSets(range);
  if (sets === null) return false;
  const includePrerelease = !!(options && options.includePrerelease);
  for (const set of sets) {
    if (set === null) continue;
    if (setAllows(parsed, set, includePrerelease)) return true;
  }
  return false;
}

function boundText(version) {
  const core = version.major + '.' + version.minor + '.' + version.patch;
  return version.prerelease.length > 0 ? core + '-' + version.prerelease.join('.') : core;
}

function takeLower(current, version, inclusive) {
  if (current === null) return { version, inclusive };
  const order = compareParsed(version, current.version);
  if (order > 0) return { version, inclusive };
  if (order === 0 && !inclusive && current.inclusive) return { version, inclusive };
  return current;
}

function takeUpper(current, version, inclusive) {
  if (current === null) return { version, inclusive };
  const order = compareParsed(version, current.version);
  if (order < 0) return { version, inclusive };
  if (order === 0 && !inclusive && current.inclusive) return { version, inclusive };
  return current;
}

function rangeBounds(range) {
  if (typeof range !== 'string') return null;
  const chunks = range.split('||');
  if (chunks.length !== 1) return null;
  const set = comparatorSet(chunks[0]);
  if (set === null) return null;
  let min = null;
  let max = null;
  for (const comparator of set) {
    const version = comparator.version;
    if (comparator.op === '>' || comparator.op === '>=') {
      min = takeLower(min, version, comparator.op === '>=');
    } else if (comparator.op === '<' || comparator.op === '<=') {
      max = takeUpper(max, version, comparator.op === '<=');
    } else {
      min = takeLower(min, version, true);
      max = takeUpper(max, version, true);
    }
  }
  return {
    min: min === null ? null : { version: boundText(min.version), inclusive: min.inclusive },
    max: max === null ? null : { version: boundText(max.version), inclusive: max.inclusive },
  };
}

module.exports = { parse, compare, satisfies, validRange, rangeBounds };

