'use strict';

const { parse, compare, satisfies, validRange } = require('./semver.js');

// Picks what to install for one dependency. The index hands back every version
// it holds for the package, in the order it happened to store them, so the
// order it arrives in says nothing about which one is newest.
function chooseVersion(request) {
  const req = request && typeof request === 'object' ? request : {};
  if (!Array.isArray(req.available) || req.available.length === 0) {
    return {
      chosen: false,
      code: 'no_versions',
      message: 'the index holds no versions for this package',
    };
  }
  if (!validRange(req.range)) {
    return {
      chosen: false,
      code: 'bad_range',
      message: 'the manifest range cannot be read: ' + String(req.range),
    };
  }
  let best = null;
  for (const entry of req.available) {
    if (parse(entry) === null) continue;
    if (!satisfies(entry, req.range, req.options)) continue;
    // Strictly greater, so equal precedence leaves the earlier entry in place.
    if (best === null || compare(entry, best) === 1) best = entry;
  }
  if (best === null) {
    return {
      chosen: false,
      code: 'no_match',
      message: 'nothing in the index matches ' + String(req.range),
    };
  }
  return { chosen: true, version: best };
}

module.exports = { chooseVersion };
